WITH valid_order_items AS (SELECT * FROM order_items WHERE quantity IS NOT NULL), order_items_stats AS (SELECT CASE WHEN unit_price >= 430 THEN 'high' WHEN unit_price >= 190 THEN 'mid' ELSE 'low' END AS unit_price_bucket, product_id, ROUND(STDDEV(unit_price), 2) AS stddev_unit_price FROM valid_order_items GROUP BY CASE WHEN unit_price >= 430 THEN 'high' WHEN unit_price >= 190 THEN 'mid' ELSE 'low' END, product_id) SELECT * FROM order_items_stats WHERE stddev_unit_price > 66 ORDER BY stddev_unit_price DESC, unit_price_bucket, product_id LIMIT 10;
